SELECT clock_timestamp() AS db_at,m.id,m.product_id,m.seller_id,m.storage_location_id,m.warehouse_id,m.quantity_delta,m.movement_type,m.created_at,m.outbound_shipment_line_id,m.transfer_group_id FROM inventory_movements m WHERE m.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND m.product_id IN (SELECT DISTINCT p.product_id FROM fbs_order_products p JOIN fbs_orders o ON o.id=p.order_id WHERE o.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND o.supply_id='b82d1e9a-30d2-4d7b-b52d-9775c3d266e3' AND o.seller_id='cf6d31c5-944b-4382-af34-636ca9aa8cc3' AND o.marketplace='ozon') AND m.movement_type='fbs_shipment' AND NOT EXISTS(SELECT 1 FROM fbs_shipment_reversal_ledger l WHERE l.tenant_id=m.tenant_id AND (l.shipment_movement_id=m.id OR l.reversal_movement_id=m.id)) AND NOT EXISTS(SELECT 1 FROM fbs_shipment_reversal_ledger l CROSS JOIN LATERAL json_array_elements(l.ozon_positions_json::json) x(value) WHERE l.tenant_id=m.tenant_id AND (x.value->>'movement_id'=m.id::text OR x.value->>'reversal_movement_id'=m.id::text)) ORDER BY m.created_at,m.id LIMIT 100
